const TIME_LIMIT: int = 1400;   // 120 buffer + 1280 attack estimate: last pair leaves ~1222 after buffer, bullets clear ~1237, tail ~43
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432;    // source type5 (Ball2), color6

xformdef VELTIME_100 {
    // EX 487 type2 ANIM(a=1): birth stage omitted by policy; its -4*0.5px retreat is kept as sh_dist(-2).
    @60 add_speed(0fx);         // EX 488 WAIT 60
    @100 set_accel(0.027fx);    // EX 489 VELTIME a=100: 0.5 -> 3.2, +2.7/100 px/frame
    set_accel(0fx);
}

async sub girl_a02_at(ways: int, after: int) {
    wait(10);                          // S:471
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 6);       // S:474 etSprite(0,5,6)
    sh_ring(0, 0);                     // S:473 etAim(0,0): aimed fan
    sh_aim(0, 1);
    sh_count(0, ways, 1);              // S:475-484: 1/1/3/3 by rank
    sh_speed(0, 0.5fx, 0fx);           // S:486 etSpeed(0,0.5,1.0), M=1 -> 0.5
    sh_dist(0, -2fx);                  // ANIM a=1 retreat kept
    sh_xform(0, VELTIME_100);          // S:487-489
    for outer in 0..10 {               // S:491 $A=10 -> 10 outer passes
        for inner in 0..10 {           // S:494 $B=10 -> 10 shots per pass
            // S:497 RANDRAD, S:497 RANDF2*32, S:498 RANDF2*2deg, in source order.
            var off_ang: angle = rand(65536) as angle;
            var u: fx = (rand(65536)-32768) as fx / 32768;
            sh_offset_rad(0, off_ang, u * 32fx);
            var uj: fx = (rand(65536)-32768) as fx / 32768;
            var jitter: angle = (uj * 364fx) as int as angle;   // 2deg = 364 BAM
            sh_angle(0, jitter, 60deg);                        // S:498 etAngle(RANDF2*2deg, 60deg)
            sh_fire(0);                                        // S:499 etOn(0)
            wait(2);                                           // S:500
        }
        wait(after);                   // S:503-512: Easy120 / Normal60 / Hard60 / Lunatic50
    }
}

async sub girl_a02(move_dir: angle, turn_dir: angle) {
    set_invuln(65535);                 // training shell
    set_hurtbox(12fx);                 // S:454 setHurtbox(24,24): source circle radius 12
    set_hitbox(8fx);                   // S:455 setHitbox(16,16): source ordinary circle w*0.5
    move_vel(0, move_dir, 0.8fx, EASE_LINEAR);      // S:456 moveVel(0,0.8); mirrored copy
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;
    var after: int = 60;
    if rank >= 2 { ways = 3; }
    if rank == 0 { after = 120; }
    if rank == 3 { after = 50; }
    spawn girl_a02_at(ways, after);    // S:457 async GirlA02_at
    wait(180);                         // S:458
    move_vel(120, turn_dir, 1.2fx, EASE_QUAD_IN);   // S:459 moveVelTime(120,1,45deg,1.2)
    loop { wait(1000); }               // S:461-464
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var y: fx = 224fx;                 // S:1236 $I0=224
    for round in 0..7 {                // S:1237 $A=7
        // S:1240 enmCreate left; S:1241 enmCreateM right (mirror). Parent stage final is (0,0).
        _ = spawn_enemy(-224fx, y, 500, 0, 0, 0, girl_a02(0deg, 45deg));
        _ = spawn_enemy(224fx, y, 500, 0, 0, 0, girl_a02(180deg, 135deg));
        y = y - 16fx;                  // S:1242
        wait(50);                      // S:1243
    }
    loop { wait(1); }
}

async sub director() {
    set_invuln(65535);
    set_hitbox(0fx);
    set_enemy_flag(ENEMY_NO_BODY, 1);  // control enemy at (0,0): no body collision
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, director);
    loop { wait(600); }
}
